cat > /tmp/build_flow.py << 'PYEOF'
import json

# Load all definitions from registry
defs = {}
for key, fname in [
    ('end', '/tmp/def_end.json'),
    ('switch', '/tmp/def_switch.json'),
    ('decision', '/tmp/def_decision.json'),
    ('merge', '/tmp/def_merge.json'),
    ('script', '/tmp/def_script.json'),
    ('agent', '/tmp/def_agent.json'),
    ('ixp', '/tmp/def_ixp.json'),
    ('apiwf', '/tmp/def_apiwf1.json'),
    ('ctx', '/tmp/def_ctx.json'),
]:
    d = json.load(open(fname))
    defs[key] = d['Data']['Node']

# Load current flow to preserve its id, version, bindings
flow = json.load(open('BillingDisputeResolution.flow'))

# Agent UUIDs
ANALYST_ID = 'ac74382f-1ec0-4ec9-ac1e-6592e293e91a'
WRITER_ID = '5a7e8ff9-0d19-44c0-9609-74abd2fc8fa9'
CTX_RES_UUID = 'cc45b9b4-dbf6-47b3-40ac-08debc0cec5b'  # same as in nodeType

# IxP model data
IXP_NODE_TYPE = 'uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178'
ixp_defaults = defs['ixp'].get('inputDefaults', {})
ixp_model_blob = ixp_defaults.get('model', {})
# Fix modelName: use modelDisplayName if modelName is null
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob.get('modelDisplayName', 'invoices-billing')

# API workflow data
APIWF_NODE_TYPE = 'uipath.core.api-workflow.07d45a91-9413-4dad-82ff-28306c2d85ea'
CTX_NODE_TYPE = 'uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b'

# Build nodes
nodes = [
    # 1. Manual Trigger
    {
        "id": "start",
        "type": "core.trigger.manual",
        "typeVersion": "1.0",
        "display": {"label": "Manual trigger"},
        "inputs": {
            "entryPointId": flow['nodes'][0]['inputs']['entryPointId'],
            "isDefaultEntryPoint": True
        }
    },
    # 2. IxP Extraction
    {
        "id": "extractInvoice",
        "type": IXP_NODE_TYPE,
        "typeVersion": "1.0.0",
        "display": {"label": "Invoice Extraction (IxP)"},
        "inputs": {
            "model": ixp_model_blob,
            "modelName": ixp_defaults.get('modelName', 'invoices-billing-f0c606f9-ixp'),
            "projectName": ixp_defaults.get('projectName', 'invoices-billing-f0c606f9-ixp'),
            "folderKey": ixp_defaults.get('folderKey', '79a7d12e-da84-4bf4-ab60-7f34b44dd178'),
            "folderName": ixp_defaults.get('folderName', 'Shared/uipath-maestro-flow/BillingDispute'),
            "versionTag": "",
            "pageRange": "",
            "fileRef": "=js:$vars.start.output.disputedInvoice"
        },
        "outputs": {
            "output": defs['ixp']['outputDefinition']['output'],
            "error": defs['ixp']['outputDefinition']['error']
        }
    },
    # 3. Script — Normalize Data
    {
        "id": "normalizeData",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Normalize Data"},
        "inputs": {
            "language": "javascript",
            "code": """var fields = ($vars.extractInvoice.output && $vars.extractInvoice.output.ExtractionResult && $vars.extractInvoice.output.ExtractionResult.ResultsDocument && $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields : [];
var normalized = fields.map(function(f) {
  return {
    Id: f.FieldId,
    Name: f.FieldName,
    Value: f.Values && f.Values.length > 0 ? f.Values[0] : null,
    Type: f.FieldType,
    IsMissing: f.IsMissing,
    Confidence: f.Confidence
  };
});
var invoiceNumberRaw = $vars.start.output.webhookPayload && $vars.start.output.webhookPayload.invoice ? $vars.start.output.webhookPayload.invoice.invoiceNumber : '';
var invoiceNumber = (invoiceNumberRaw || '').trim().toUpperCase();
if (!invoiceNumber.startsWith('MCS-')) { invoiceNumber = 'MCS-' + invoiceNumber; }
return { normalizedFields: normalized, normalizedInvoiceNumber: invoiceNumber };"""
        },
        "outputs": {
            "output": {"type": "object", "description": "Normalized invoice data", "source": "=result", "var": "output"}
        }
    },
    # 4. CRM Lookup (connector - already added by node add)
    {
        "id": "crmLookup1",
        "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
        "typeVersion": "1.0.0",
        "display": {"label": "CRM Lookup"},
        "inputs": {}
    },
    # 5. ERP Lookup (connector - already added by node add)
    {
        "id": "erpLookup1",
        "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
        "typeVersion": "1.0.0",
        "display": {"label": "ERP Lookup"},
        "inputs": {}
    },
    # 6. Merge
    {
        "id": "mergeResults",
        "type": "core.logic.merge",
        "typeVersion": "1.0",
        "display": {"label": "Merge"},
        "inputs": {}
    },
    # 7. Script — Discrepancy Detection
    {
        "id": "detectDiscrepancies",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Discrepancy Detection"},
        "inputs": {
            "language": "javascript",
            "code": """var disputedItems = ($vars.start.output.webhookPayload && $vars.start.output.webhookPayload.dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems) ? $vars.start.output.webhookPayload.dispute.disputedLineItems : [];
var erpRecords = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) ? $vars.erpLookup1.output.value : ($vars.erpLookup1.output ? $vars.erpLookup1.output : []);
var mismatches = [];
var totalOvercharge = 0;
var totalUndercharge = 0;
disputedItems.forEach(function(item) {
  var erpRow = null;
  if (Array.isArray(erpRecords)) {
    erpRow = erpRecords.find(function(r) { return r.lineNumber === item.lineNumber || r.LineNumber === item.lineNumber; });
  }
  if (!erpRow) {
    mismatches.push({ lineNumber: item.lineNumber, description: item.description, disputedAmount: item.amount, contractAmount: null, difference: null, note: 'Not found in ERP' });
    return;
  }
  var contractAmt = parseFloat(erpRow.amount || erpRow.Amount || item.amount);
  var disputedAmt = parseFloat(item.amount);
  var diff = disputedAmt - contractAmt;
  if (Math.abs(diff) > 0.01) {
    if (diff > 0) { totalOvercharge += diff; } else { totalUndercharge += Math.abs(diff); }
    mismatches.push({ lineNumber: item.lineNumber, description: item.description, disputedAmount: disputedAmt, contractAmount: contractAmt, difference: diff, note: diff > 0 ? 'Overcharge' : 'Undercharge' });
  }
});
return { mismatches: mismatches, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge, mismatchCount: mismatches.length };"""
        },
        "outputs": {
            "output": {"type": "object", "description": "Discrepancy analysis result", "source": "=result", "var": "output"}
        }
    },
    # 8. Dispute Analyst Agent
    {
        "id": "disputeAnalyst",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.2",
        "display": {"label": "Dispute Analyst Agent"},
        "inputs": {
            "systemPrompt": "You are a billing dispute analyst. Analyze the provided invoice data, ERP records, CRM records, and discrepancy summary to determine a resolution.",
            "userPrompt": "Analyze billing dispute and return a structured determination.",
            "source": ANALYST_ID,
            "agentInputVariables": [
                {"id": "normalizeData__output__normalizedFields", "type": "object", "binding": "=$vars.normalizeData.output.normalizedFields"},
                {"id": "normalizeData__output__normalizedInvoiceNumber", "type": "string", "binding": "=$vars.normalizeData.output.normalizedInvoiceNumber"},
                {"id": "crmLookup1__output", "type": "object", "binding": "=$vars.crmLookup1.output"},
                {"id": "erpLookup1__output", "type": "object", "binding": "=$vars.erpLookup1.output"},
                {"id": "detectDiscrepancies__output__mismatches", "type": "object", "binding": "=$vars.detectDiscrepancies.output.mismatches"},
                {"id": "detectDiscrepancies__output__totalOvercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalOvercharge"},
                {"id": "detectDiscrepancies__output__totalUndercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalUndercharge"},
                {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload"}
            ],
            "agentOutputVariables": [
                {"id": "determination", "type": "string"},
                {"id": "recommendedAction", "type": "string"},
                {"id": "autoResolutionEligible", "type": "boolean"},
                {"id": "creditAmount", "type": "number"},
                {"id": "confidence", "type": "number"},
                {"id": "rationale", "type": "string"}
            ]
        },
        "outputs": {
            "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
            "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 9. Context node for Analyst
    {
        "id": "analyistContextNode",
        "type": CTX_NODE_TYPE,
        "typeVersion": "1.0.0",
        "display": {"label": "Billing Dispute SOP Index"},
        "inputs": {"source": CTX_RES_UUID}
    },
    # 10. Switch on recommendedAction
    {
        "id": "switchOnAction",
        "type": "core.logic.switch",
        "typeVersion": "1.1",
        "display": {"label": "Switch on recommendedAction"},
        "inputs": {
            "cases": [
                {"id": "escalate", "label": "escalate_to_manager", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'escalate_to_manager'"},
                {"id": "auto_resolve", "label": "auto_resolve", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'auto_resolve'"},
                {"id": "reject", "label": "reject", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'reject'"}
            ]
        }
    },
    # 11. Approval Decision (core.logic.decision) - default approved
    {
        "id": "approvalDecision",
        "type": "core.logic.decision",
        "typeVersion": "1.1",
        "display": {"label": "Approval Decision"},
        "inputs": {
            "expression": "false",
            "trueLabel": "Rejected",
            "falseLabel": "Approved"
        }
    },
    # 12. Script — Log Credit Amount (for auto_resolve path)
    {
        "id": "logCreditAmount",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Log Credit Amount"},
        "inputs": {
            "language": "javascript",
            "code": "return { creditAmount: $vars.disputeAnalyst.output.creditAmount };"
        },
        "outputs": {
            "output": {"type": "object", "description": "Credit amount logged", "source": "=result", "var": "output"}
        }
    },
    # 13. FinancialPostingFunction (API workflow)
    {
        "id": "financialPosting",
        "type": APIWF_NODE_TYPE,
        "typeVersion": "1.0.0",
        "display": {"label": "Financial Posting Function"},
        "inputs": {
            "invoiceNumber": "=js:$vars.normalizeData.output.normalizedInvoiceNumber"
        },
