            "error": {"type": "object", "description": "Error information if the API workflow fails", "source": "=result.Error", "var": "error"}
        }
    },
    # 14. Resolution Writer Agent
    {
        "id": "resolutionWriter",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.2",
